from AlgorithmImports import *
import math


class ExactStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data: Slice):
        symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        available = {}
        for symbol in symbols:
            if data.ContainsKey(symbol) and data[symbol] is not None:
                available[symbol] = data[symbol]

        if self.aapl in available:
            aapl_close = available[self.aapl].Close

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                elif aapl_close > self.previous_aapl_close:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        if self.spy not in available:
            return

        spy_close = available[self.spy].Close
        current_spy_sma = self.spy_sma.Current.Value

        spy_crosses_above = (
            self.spy_sma.IsReady
            and self.previous_spy_sma is not None
            and self.previous_spy_sma >= self.previous_spy_close
            and spy_close > current_spy_sma
        )

        spy_crosses_below = (
            self.spy_sma.IsReady
            and self.previous_spy_sma is not None
            and self.previous_spy_close <= self.previous_spy_sma
            and spy_close < current_spy_sma
        )

        if self.spy_sma.IsReady and self.previous_spy_sma is not None:
            if self.strategy_a_lot > 0 and spy_crosses_below:
                self.MarketOrder(
                    self.spy,
                    -self.strategy_a_lot,
                    tag="StrategyA Sell"
                )

            if self.strategy_a_lot == 0 and spy_crosses_above:
                quantity = int(
                    math.floor(
                        0.40 * self.Portfolio.TotalPortfolioValue / spy_close
                    )
                )
                if quantity > 0:
                    self.MarketOrder(
                        self.spy,
                        quantity,
                        tag="StrategyA Buy"
                    )

        if self.aapl in available:
            aapl_close = available[self.aapl].Close

            b_sold_this_bar = False

            if (
                self.strategy_b_lot > 0
                and self.aapl_rsi.IsReady
                and self.aapl_rsi.Current.Value > 60
            ):
                self.MarketOrder(
                    self.aapl,
                    -self.strategy_b_lot,
                    tag="StrategyB Sell"
                )
                b_sold_this_bar = True

            if (
                (self.strategy_b_lot == 0 or b_sold_this_bar)
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20000
            ):
                quantity = int(math.floor(20000 / aapl_close))
                if quantity > 0:
                    self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="StrategyB Buy"
                    )

        if self.spy_sma.IsReady:
            self.previous_spy_sma = current_spy_sma
            self.previous_spy_close = spy_close

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.Status != OrderStatus.Filled:
            return

        fill_quantity = orderEvent.FillQuantity
        tag = orderEvent.Tag or ""

        if "StrategyA" in tag:
            self.strategy_a_lot += fill_quantity
            self.strategy_a_lot = max(0, self.strategy_a_lot)

        elif "StrategyB" in tag:
            self.strategy_b_lot += fill_quantity
            self.strategy_b_lot = max(0, self.strategy_b_lot)
