from AlgorithmImports import *


class TwoSlotStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.lots = {
            "StrategyA": 0,
            "StrategyB": 0
        }

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = {}

        for symbol in self.symbols:
            if not data.Bars.ContainsKey(symbol):
                bars = None
                break
            bars[symbol] = data.Bars[symbol]

        if bars is not None:
            self.spy_sma.Update(bars[self.spy].EndTime, bars[self.spy].Close)
            self.aapl_rsi.Update(bars[self.aapl].EndTime, bars[self.aapl].Close)

            if self.previous_aapl_close is not None:
                if bars[self.aapl].Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            if not self.IsWarmingUp:
                self.EvaluateSells(bars)
                self.EvaluateBuys(bars)

            self.previous_spy_close = bars[self.spy].Close
            self.previous_spy_sma = self.spy_sma.Current.Value
            self.previous_aapl_close = bars[self.aapl].Close

        else:
            if data.Bars.ContainsKey(self.aapl):
                aapl_close = data.Bars[self.aapl].Close
                if self.previous_aapl_close is not None:
                    if aapl_close < self.previous_aapl_close:
                        self.aapl_red_streak += 1
                    else:
                        self.aapl_red_streak = 0
                self.previous_aapl_close = aapl_close

            if data.Bars.ContainsKey(self.spy) and self.spy_sma.IsReady:
                self.previous_spy_close = data.Bars[self.spy].Close
                self.previous_spy_sma = self.spy_sma.Current.Value

    def EvaluateSells(self, bars):
        if self.spy_sma.IsReady and self.lots["StrategyA"] > 0:
            spy_close = bars[self.spy].Close
            spy_sma = self.spy_sma.Current.Value

            crosses_below = (
                self.previous_spy_close is not None and
                self.previous_spy_sma is not None and
                self.previous_spy_close >= self.previous_spy_sma and
                spy_close < spy_sma
            )

            if crosses_below:
                self.MarketOrder(
                    self.spy,
                    -self.lots["StrategyA"],
                    tag="StrategyA"
                )

        if self.aapl_rsi.IsReady and self.lots["StrategyB"] > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(
                    self.aapl,
                    -self.lots["StrategyB"],
                    tag="StrategyB"
                )

    def EvaluateBuys(self, bars):
        if self.spy_sma.IsReady and self.lots["StrategyA"] == 0:
            spy_close = bars[self.spy].Close
            spy_sma = self.spy_sma.Current.Value

            crosses_above = (
                self.previous_spy_close is not None and
                self.previous_spy_sma is not None and
                self.previous_spy_close <= self.previous_spy_sma and
                spy_close > spy_sma
            )

            if crosses_above:
                quantity = int(
                    (0.40 * self.Portfolio.TotalPortfolioValue) / spy_close
                )
                if quantity > 0:
                    self.MarketOrder(
                        self.spy,
                        quantity,
                        tag="StrategyA"
                    )

        if self.lots["StrategyB"] == 0 and self.aapl_red_streak >= 3:
            aapl_close = bars[self.aapl].Close
            if self.Portfolio.Cash >= 20000:
                quantity = int(20000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="StrategyB"
                    )

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        tag = order_event.Tag
        if tag not in self.lots:
            return

        self.lots[tag] += int(order_event.FillQuantity)
        self.lots[tag] = max(0, self.lots[tag])
